template <typename T,typename U>
std::pair<T,U> operator+(const std::pair<T,U> & l,const std::pair<T,U> & r) {
  return {l.first+r.first,l.second+r.second};
} 
typedef void (*callback_function)(void); // type for conciseness
const long long ZERO = 0LL;
const long long INF64 = 1e18;
const int INF32 = 1e9;
const int MOD = 1e9 + 7;
const double PI = acos(-1.0L);
const double EPS = static_cast<double>(1e-9);
typedef long long ll;

int norm(int a) {
  return ((a % MOD) + MOD) % MOD;
}

int mul(int a, int b) {
  return int(a * 1LL * b % MOD);
}

int binPow(int a, int k) {
  int ans = 1;
  for (; k > 0; k >>= 1) {
    if (k & 1) {
      ans = mul(ans, a);
    }
    a = mul(a, a);
  }
  return ans;
}

// If I need to find (x / a) % MOD, I need to use this function:
//    (x / a) % MOD = (x * inv(a)) % MOD
int inv(int a) {
  int b = binPow(a, MOD - 2);
  assert(mul(a, b) == 1);
  return b;
}

struct Edge {
  int y;
  int capacity;
  int flow;
  int cost;

  Edge() {};

  Edge(int _y, int _capacity, int _flow, int _cost) 
    : y(_y), capacity(_capacity), flow(_flow), cost(_cost) {};
};

vec<Edge> e;

const int N = 1e6 + 7;
vec<int> g[N];

ll ans = 0;
ll dist[N];
int pred[N];
int pe[N];
int inq[N];

int source = N - 2;
int target = N - 1;

int residualCapacity(int x) {
  return e[x].capacity - e[x].flow;
}

void pushFlow() {
  FOR(i, 0, N) {
    dist[i] = INF64;
    pred[i] = -1;
    pe[i] = -1;
    inq[i] = 0;
  }
  dist[source] = 0;
  queue<int> q;
  q.push(source);
  inq[source] = 1;
  while (!q.empty()) {
    int k = q.front(); q.pop();
    inq[k] = 0;
    for (auto x : g[k]) {
      if (!residualCapacity(x)) {
        continue;
      }
      int cost = e[x].cost;
      int y = e[x].y;
      if (dist[y] > dist[k] + cost) {
        dist[y] = dist[k] + cost;
        pred[y] = k;
        pe[y] = x;
        if (inq[y] == 0) {
          inq[y] = 1;
          q.push(y);
        }
      }
    }
  }
  int cur = target;
  //vec<int> zz(1, cur);
  while (cur != source) {
    e[pe[cur]].flow++;
    e[pe[cur] ^ 1].flow--;
    cur = pred[cur];
    //zz.push_back(cur);
  }
  //reverse(zz.begin(), zz.end());
