  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  FOR(i, 0, k) {
    int x;
    scanf("%d", &x);
    --x;
    addEdge(source, x, 1, 0);
  }
  int timeLayers = 101;
  FOR(i, 0, timeLayers) {
    addEdge(i * n, target, k, i * c);
  }
  FOR(i, 0, m) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x, --y;
    FOR(i, 0, timeLayers - 1) FOR(j, 0, k) {
      addEdge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
    }
    FOR(i, 0, timeLayers - 1) FOR(j, 0, k) {
      addEdge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
    }
  }
  FOR(i, 0, n) FOR(j, 0, timeLayers - 1) {
    addEdge(i + j * n, i + j * n + n, k, 0);
  }
  FOR(i, 0, k) {
    pushFlow();
  }
  printf("%lld\n", ans);
}

